struct RClass* get_real_class(struct RClass* cl) {
  if (!cl) {
    return NULL;
  }

  while (cl) {
    if (RCLASS_CLASSTYPE(cl) != 0 || RCLASS_SUPER(cl) == 0) {
      break;
    }
    cl = RCLASS_SUPER(cl);
  }

  return cl;
}

struct RClass* get_real_class(struct RClass* cl) {
  if (cl == NULL) {
    return NULL;
  }

  while (cl != NULL) {
    if (!(cl->flags & MRB_CLASS_FLAG_SINGLETON) && !(cl->flags & MRB_CLASS_FLAG_INCLUDED)) {
      return cl;
    }
    cl = cl->super;
  }

  return NULL;
}

